 void require(boolean b,String m){checks++;if(!b)throw new AssertionError(m);}
 interface Test{boolean get()throws Exception;}
 void waitFor(Test t,long ms,String m)throws Exception{long end=SystemClock.elapsedRealtime()+ms;while(SystemClock.elapsedRealtime()<end){if(t.get())return;Thread.sleep(100);}throw new AssertionError(m);}
 public void onStart(){Bundle r=new Bundle();try{c=new BridgeContext(getTargetContext());engine=TransferEngine.get(c);io=new CancellationScope(Runnable::run,()->{});ledger=new RestoreLedger(c);ActivityMonitor monitor=addMonitor(UniversalActivity.class.getName(),null,false);c.startActivity(new Intent(c,UniversalActivity.class).putExtra("receiving",false).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));activity=monitor.waitForActivityWithTimeout(10000);require(activity!=null,"activity foreground");String mode=options.getString("mode","restore");if(mode.equals("install"))install();else if(mode.equals("cancel"))cancel();else restore();r.putInt("checks",checks);r.putString("phase",phase);r.putBoolean("physicalDeviceProof",false);finish(Activity.RESULT_OK,r);}catch(Throwable e){r.putString("failure",phase+":"+e.getClass().getSimpleName()+":"+(e instanceof AssertionError?e.getMessage():"runtime failure - inspect phase"));r.putInt("checks",checks);finish(Activity.RESULT_CANCELED,r);}finally{if(ledger!=null)ledger.close();for(File f:temps)f.delete();}}
 File file(byte[] b)throws Exception{File f=File.createTempFile("synthetic-",".bin",c.getCacheDir());try(FileOutputStream out=new FileOutputStream(f)){out.write(b);}temps.add(f);return f;}
 TransferStore.MediaReceipt receipt(Uri dir,String name,String mime,byte[] bytes)throws Exception{File f=file(bytes);ProtocolCore.Item item=new ProtocolCore.Item(ProtocolCore.token(16),name,mime,bytes.length,MessageDigest.getInstance("SHA-256").digest(bytes));engine.store.received(ProtocolCore.token(16),item,Uri.fromFile(f),dir);return new TransferStore.MediaReceipt(1,item,Uri.fromFile(f));}
 long markerCount(String key)throws Exception{try(Cursor q=c.getContentResolver().query(ContactsContract.Data.CONTENT_URI,new String[]{"_id"},"mimetype=? AND data1=?",new String[]{ContactImporter.MARKER,key},null)){return q.getCount();}}
 void restore()throws Exception{
  phase="contacts";String hash=ProtocolCore.token(16);String vcf="BEGIN:VCARD\r\nVERSION:3.0\r\nFN:ChinaTech Synthetic 王😀 "+ProtocolCore.token(8)+"\r\nN:Test;Synthetic;;;\r\nTEL;TYPE=CELL:+390000001\r\nEMAIL;TYPE=WORK:test@example.invalid\r\nADR;TYPE=HOME:;;Road;City;Region;00000;Italy\r\nORG:Synthetic;Test\r\nTITLE:Repair\r\nNOTE:synthetic\\nonly\r\nBDAY:2000-01-02\r\nX-UNKNOWN:preserved-in-vcf\r\nEND:VCARD\r\n";File f=file(vcf.getBytes(StandardCharsets.UTF_8));try(RestoreText.Reader reader=new RestoreText.Reader(new FileInputStream(f))){hash=reader.next("VCARD").fingerprint();}ContactImporter importer=new ContactImporter(c,io,ledger);ContactImporter.Result first=importer.run(f,hash,(k,a,b,p,e)->{});require(first.imported==1&&first.partial==1&&first.failed==0,"actual local contact partial accurately reported");require(markerCount("contact:"+hash+":1")==1,"one atomic provider marker");ContactImporter.Result again=importer.run(f,hash,(k,a,b,p,e)->{});require(again.existing==1&&again.imported==0&&again.partial==1,"contact retry no duplicate and partial fact retained");File expanded=file((vcf+"BEGIN:VCARD\nVERSION:3.0\nFN:Second synthetic "+ProtocolCore.token(8)+"\nTEL:+390000003\nEND:VCARD\n").getBytes(StandardCharsets.UTF_8));ContactImporter.Result changed=importer.run(expanded,ProtocolCore.token(16),(k,a,b,p,e)->{});require(changed.existing==1&&changed.imported==1&&changed.partial==1,"changed aggregate export preserves unchanged record identity");long raw=Long.parseLong(ledger.get("contact:"+hash+":1").dest);ContentValues edit=new ContentValues();edit.put(ContactsContract.CommonDataKinds.Phone.NUMBER,"+390000002");c.getContentResolver().update(ContactsContract.Data.CONTENT_URI,edit,"raw_contact_id=? AND mimetype=?",new String[]{Long.toString(raw),ContactsContract.CommonDataKinds.Phone.CONTENT_ITEM_TYPE});importer.run(f,hash,(k,a,b,p,e)->{});try(Cursor q=c.getContentResolver().query(ContactsContract.Data.CONTENT_URI,new String[]{"data1"},"raw_contact_id=? AND mimetype=?",new String[]{Long.toString(raw),ContactsContract.CommonDataKinds.Phone.CONTENT_ITEM_TYPE},null)){require(q.moveToFirst()&&q.getString(0).equals("+390000002"),"edited existing contact preserved");}
  phase="contact-journal-gap";ledger.getWritableDatabase().delete("restored","k=?",new String[]{"contact:"+hash+":1"});ContactImporter.Result gap=importer.run(f,hash,(k,a,b,p,e)->{});require(gap.existing==1&&gap.partial==1&&markerCount("contact:"+hash+":1")==1,"provider commit gap recovers marker");
  phase="calendar";String calName="CT-synthetic-"+ProtocolCore.token(8);Uri sync=CalendarContract.Calendars.CONTENT_URI.buildUpon().appendQueryParameter(CalendarContract.CALLER_IS_SYNCADAPTER,"true").appendQueryParameter(CalendarContract.Calendars.ACCOUNT_NAME,calName).appendQueryParameter(CalendarContract.Calendars.ACCOUNT_TYPE,CalendarContract.ACCOUNT_TYPE_LOCAL).build();ContentValues cv=new ContentValues();cv.put("account_name",calName);cv.put("account_type",CalendarContract.ACCOUNT_TYPE_LOCAL);cv.put("name",calName);cv.put("calendar_displayName",calName);cv.put("calendar_color",0xff5500ff);cv.put("calendar_access_level",CalendarContract.Calendars.CAL_ACCESS_OWNER);cv.put("ownerAccount",calName);cv.put("calendar_timezone","UTC");cv.put("sync_events",1);Uri cal=c.getContentResolver().insert(sync,cv);require(cal!=null,"synthetic writable calendar");long calId=ContentUris.parseId(cal);String ics="BEGIN:VCALENDAR\nVERSION:2.0\nBEGIN:VEVENT\nUID:synthetic\nDTSTAMP:20261009T000000Z\nDTSTART:20261010T100000Z\nDTEND:20261010T110000Z\nSUMMARY:CT synthetic only\nEND:VEVENT\nEND:VCALENDAR\n";File event=file(ics.getBytes(StandardCharsets.UTF_8));String eh=ProtocolCore.token(16);require(CalendarImporter.run(c,io,ledger,event,eh,calId,(k,a,b,p,e)->{}).imported==1,"actual event inserted");require(CalendarImporter.run(c,io,ledger,event,eh,calId,(k,a,b,p,e)->{}).existing==1,"event retry no duplicate");try(Cursor q=c.getContentResolver().query(CalendarContract.Events.CONTENT_URI,new String[]{"dtstart","dtend"},"calendar_id=?",new String[]{Long.toString(calId)},null)){require(q.moveToFirst()&&q.getLong(0)==1791626400000L&&q.getLong(1)-q.getLong(0)==3600000,"event UTC exact");}
  phase="media";Uri dir=Uri.parse("content://ctpa-synthetic/"+ProtocolCore.token(8));byte[] png=Base64.getDecoder().decode("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+aWQAAAABJRU5ErkJggg==");TransferStore.MediaReceipt mediaRow=receipt(dir,"synthetic.png","image/png",png);MediaImporter media=new MediaImporter(c,io);require(media.publish(mediaRow),"actual gallery publish");require(!media.publish(mediaRow),"gallery retry skips exact owned copy");MediaImportStore ms=new MediaImportStore(c);String mk=ProtocolCore.hex(mediaRow.item.hash)+":"+mediaRow.item.size+":"+mediaRow.item.mime;Uri published=ms.get(mk).dest;try(OutputStream out=c.getContentResolver().openOutputStream(published,"w")){out.write(new byte[]{1,2,3});}try{media.publish(mediaRow);throw new AssertionError("edited gallery accepted");}catch(IOException expected){checks++;}try(Cursor q=c.getContentResolver().query(published,new String[]{"_id"},null,null,null)){require(q.moveToFirst(),"edited published gallery retained");}c.getContentResolver().delete(published,null,null);ms.close();media.close();
  phase="copy-integrity";TransferStore.MediaReceipt bad=receipt(dir,"bad.vcf","text/x-vcard",vcf.getBytes(StandardCharsets.UTF_8));try(FileOutputStream out=new FileOutputStream(bad.source.getPath())){out.write(new byte[]{0});}try{RestoreCatalog.checkedCopy(c,bad,io);throw new AssertionError("changed receipt accepted");}catch(IOException expected){checks++;}
  phase="automatic-queue";Uri autoDir=Uri.parse("content://ctpa-synthetic/"+ProtocolCore.token(8));receipt(autoDir,"synthetic.txt","text/plain",new byte[]{1});RestoreCoordinator rc=RestoreCoordinator.get(c);rc.configure(new boolean[]{false,true,false,false},-1,true);rc.beginSetup();engine.setDirectory(autoDir);engine.store.restoreReady("synthetic-ready",autoDir);runOnMainSync(()->rc.observeCompletion(engine));require(!rc.isActive(),"unfinished permission setup blocks automatic restore");rc.finishSetup();runOnMainSync(()->rc.observeCompletion(engine));waitFor(()->!rc.isActive(),10000,"automatic archived queue finished");require(rc.files==1&&!rc.needsResume(),"automatic completion separates archived-only data");runOnMainSync(()->rc.observeCompletion(engine));require(!rc.isActive(),"completion reattach does not replay");
  phase="cleanup";c.getContentResolver().delete(ContentUris.withAppendedId(ContactsContract.RawContacts.CONTENT_URI,raw),null,null);c.getContentResolver().delete(sync.buildUpon().appendPath(Long.toString(calId)).build(),null,null);rc.configure(new boolean[]{true,true,true,true},-1,false);phase="complete";
 }
 void install()throws Exception{phase="install-queue";File archive=new File("/data/local/tmp/mimover-synthetic-app.zip");byte[] bytes=new byte[(int)archive.length()];try(DataInputStream in=new DataInputStream(new FileInputStream(archive))){in.readFully(bytes);}Uri dir=Uri.parse("content://ctpa-synthetic/"+ProtocolCore.token(8));TransferStore.MediaReceipt row=receipt(dir,"in.chinatech.synthetic.restore-ChinaTech-APK.zip","application/zip",bytes);String key="app:"+ProtocolCore.hex(row.item.hash);RestoreCoordinator rc=RestoreCoordinator.get(c);rc.configure(new boolean[]{false,false,false,true},-1,false);runOnMainSync(()->rc.start(dir,"synthetic-install"));waitFor(()->ledger.get(key)!=null&&ledger.get(key).state.equals("waiting"),20000,"system confirmation callback");require(rc.isActive(),"restore queue stays active while waiting for Android");require(!AppInstaller.installed(c,"in.chinatech.synthetic.restore"),"not installed before user confirmation");boolean clicked=false;long end=SystemClock.elapsedRealtime()+25000;while(SystemClock.elapsedRealtime()<end){AccessibilityNodeInfo root=getUiAutomation().getRootInActiveWindow();if(root!=null){for(String id:new String[]{"com.android.packageinstaller:id/install_button","com.google.android.packageinstaller:id/install_button","android:id/button1"})for(AccessibilityNodeInfo n:root.findAccessibilityNodeInfosByViewId(id))if(n.isClickable()&&n.isEnabled()&&n.getText()!=null&&(n.getText().toString().equalsIgnoreCase("Install")||n.getText().toString().equalsIgnoreCase("Installa"))){clicked=n.performAction(AccessibilityNodeInfo.ACTION_CLICK);}}if(clicked)break;Thread.sleep(200);}require(clicked,"actual Android confirmation clicked for synthetic app");waitFor(()->!rc.isActive(),45000,"system install queue finished");require(ledger.get(key).state.equals("done")&&rc.imported==1&&rc.failed==0,"system success counted by restoration queue");PackageInfo pkg=c.getPackageManager().getPackageInfo("in.chinatech.synthetic.restore",0);require(pkg.applicationInfo.splitSourceDirs!=null&&pkg.applicationInfo.splitSourceDirs.length==1,"actual base and split installed");AppInstaller.Prepared repeat=AppInstaller.prepare(c,io,ledger,key,archive);require(repeat.session==-1&&ledger.get(key).state.equals("existing"),"installed package skipped");phase="malicious-zip";File bad=file(new byte[0]);try(ZipOutputStream z=new ZipOutputStream(new FileOutputStream(bad))){z.putNextEntry(new ZipEntry("../base.apk"));z.write(new byte[]{1});z.closeEntry();}try{AppInstaller.prepare(c,io,ledger,"bad",bad);throw new AssertionError("ZIP path accepted");}catch(IOException expected){checks++;}require(!ledger.installation(key,3,"wrong","failed"),"stale callback cannot downgrade terminal fact");phase="complete";}
 Intent getPendingConfirmation(RestoreCoordinator rc)throws Exception{java.lang.reflect.Field f=RestoreCoordinator.class.getDeclaredField("confirmation");f.setAccessible(true);return (Intent)f.get(rc);}
 void cancel()throws Exception {phase="installation-cancel";File archive=new File("/data/local/tmp/mimover-synthetic-cancel.zip");byte[] bytes=new byte[(int)archive.length()];try(DataInputStream in=new DataInputStream(new FileInputStream(archive))){in.readFully(bytes);}Uri dir=Uri.parse("content://ctpa-synthetic/"+ProtocolCore.token(8));TransferStore.MediaReceipt row=receipt(dir,"synthetic-cancel-ChinaTech-APK.zip","application/zip",bytes);String key="app:"+ProtocolCore.hex(row.item.hash);RestoreCoordinator rc=RestoreCoordinator.get(c);rc.configure(new boolean[]{false,false,false,true},-1,false);runOnMainSync(()->rc.start(dir,"cancel-fixture"));waitFor(()->ledger.get(key)!=null&&ledger.get(key).state.equals("waiting"),20000,"cancel confirmation callback");RestoreLedger.Entry old=ledger.get(key);runOnMainSync(rc::skipInstallation);waitFor(()->!rc.isActive(),10000,"queue skip finishes");require(rc.failed==1&&!AppInstaller.installed(c,"in.chinatech.synthetic.cancel"),"cancel does not count installed or install package");Intent stale=new Intent().putExtra("restore-key",key).putExtra("restore-token",old.token).putExtra(PackageInstaller.EXTRA_SESSION_ID,old.session).putExtra(PackageInstaller.EXTRA_STATUS,PackageInstaller.STATUS_PENDING_USER_ACTION).putExtra(Intent.EXTRA_INTENT,new Intent(Intent.ACTION_VIEW));rc.installationResult(stale);require(!rc.needsInstallation()&&!rc.isActive(),"late pending action cannot revive cancelled queue");rc.installationResult(new Intent(stale).putExtra(PackageInstaller.EXTRA_STATUS,PackageInstaller.STATUS_SUCCESS));require(ledger.get(key).state.equals("failed"),"late success cannot overwrite cancelled fact");phase="complete";}
